        long days = shop->GetDaysTillRestock(itemDefIndex);
        text = bank.GetTextBySymbol(miscDef->TradeDeliveryString.ToCharString()) + miscDef->ColonSeparator + miscDef->SpaceSeparator;
        if (days != 0)
