        text = CWideString::NullString;
        static_cast<const CTCInventoryWeapons*>(inventory)->GetItemDescriptionNoDamageNorWeight(text, itemDefIndex, selling);
        description->AddChild(textComponent);
        line->SetValue(text, true, true);
    }
    }
