        else
            subList.Reset(ConstructClothingListPC(partLists[i], viewport, frame, parts[i], false));
        if (!subList.IsNull())
            entry->AddChild(subList);
        else
            entry->MakeUnavailable();
    }
    list->SetDefaultChild(defaultChild);
    ClothingList = list;
    return list;
}

