        for (int s = 0; s < 6; ++s) {
            if (secs[s].v->empty()) continue;
            partLists.push_back(*secs[s].v);
            partNames.push_back(Text(secs[s].name));
            descriptions.push_back(CreateMenuDescPC(secs[s].guide));
